/**
 * Test Case: Logout
 *
 * Tags: @master @regression @web
 *
 * Steps:
 * 1) Log in with valid credentials and verify authentication
 * 2) Click Logout and verify the logout confirmation page
 * 3) Click Continue and verify the redirect to the home page
 * 4) Verify authenticated account options are no longer available
 */

// Generated by GitHub Copilot - Nov-23-2026
import { test, expect } from '../../fixtures/pageFixtures';
import { Helper } from '../../utils/helper';

test('User logout test @master @regression @web', async ({ homePage, loginPage, myAccountPage, logoutPage }) => {
    const { email, password } = Helper.getLoginDetails();

    await test.step('1) Log in with valid credentials', async () => {
        await homePage.clickMyAccount();
        await homePage.clickLogin();
        await loginPage.login(email, password);
        expect(await myAccountPage.isMyAccountPageExists()).toBeTruthy();
    });

    await test.step('2) Log out and verify the logout page', async () => {
        await myAccountPage.clickLogout();
        expect(await logoutPage.isLogoutPageExists()).toBeTruthy();
    });

    await test.step('3) Continue and verify the redirect to the home page', async () => {
        await logoutPage.clickContinue();
        expect(await homePage.isHomePageExists()).toBeTruthy();
    });

    await test.step('4) Verify authenticated options are no longer available', async () => {
        await homePage.clickMyAccount();
        expect(await homePage.isLoginOptionExists()).toBeTruthy();
        expect(await homePage.isLogoutOptionExists()).toBeFalsy();
    });

    console.log('✅ ✔️ Logout completed successfully!');
});
